import type { ElementTable } from 'claude-code'

import type { AccountView, AccountsTabKey, CodexAccountView, StorageView, UsageSummary, UsageView } from '../../types'
import type { Locale, Messages } from '../i18n'
import { ChoiceDialog, Dialog, Header, InputDialog, TabBar, Tiles } from '../shared/kit'
import type { DialogLine, HeaderInfo } from '../shared/kit'
import { byteSize } from '../storage'
import { AccountsTab } from './accounts'
import { StorageTab } from './storage'
import { UsageTab } from './usage'
import { WebhookDialog } from './webhook'
import type { WebhookModel } from './webhook'

/**
 * The accounts pane: a dialog in place of the tabs while one asks, else the
 * header, the tab bar and the tab on screen. Pure: the hooks module reads the
 * state into the model and builds the actions over `$`.
 */

/** The idle ages a cleanup offers, in days. */
export const CLEANUP_DAYS = [7, 14, 30, 90]
/** The periods the Usage tab offers, in days; 0 is everything counted. */
export const USAGE_PERIODS = [7, 30, 0]

export type PaneDialog =
  | { kind: 'remove'; uuid: string }
  | { kind: 'switch'; uuid: string }
  | { kind: 'webhook' }
  | { kind: 'period' }
  | { kind: 'cleanupDays' }
  | { kind: 'cleanup' }
  | null

export type PaneModel = {
  m: Messages
  locale: Locale
  bodyColumns: number
  /** Whether the surface has a text field (every one but mobile). */
  hasField: boolean
  header: HeaderInfo
  dialog: PaneDialog
  focused: string | null
  tab: AccountsTabKey
  accounts: AccountView[]
  liveUuid: string | null
  /** The account this session's requests go out under: the host's where the app runs it, else the live one. */
  sessionUuid: string | null
  readings: Record<string, UsageView>
  /** The Codex account this session's Codex uses; null where the Codex CLI does not run. */
  codex: CodexAccountView | null
  isGuideShown: boolean
  isRefreshing: boolean
  now: number
  /** Whether Orca writes the Claude login here, so a switch selects the account there too. */
  isOrcaSelecting: boolean
  webhook: Pick<WebhookModel, 'draft' | 'templatePath' | 'preview' | 'urlProblem' | 'lastSend'> | null
  usage: { summary: UsageSummary | null; scan: { done: number; total: number } | null; error: string | null; period: number }
  storage: { view: StorageView | null; cleanupDays: number; asked: { count: number; bytes: number } }
}

/** Each action is already wrapped by the hooks module: it runs, and what it returns or throws becomes a toast. */
export type PaneActions = {
  dismiss: () => void
  selectTab: (key: AccountsTabKey) => void
  askSwitch: (uuid: string) => void
  askRemove: (uuid: string) => void
  switchTo: (uuid: string) => void
  remove: (uuid: string) => void
  refresh: () => void
  toggleGuide: () => void
  openWebhook: () => void
  webhook: {
    toggle: () => void
    toggleMethod: () => void
    setUrl: (url: string) => void
    setToken: (token: string) => void
    clearToken: () => void
    test: () => void
    save: () => void
    cancel: () => void
  }
  choosePeriod: () => void
  setPeriod: (days: number) => void
  countUsage: () => void
  chooseCleanupDays: () => void
  setCleanupDays: (days: number) => void
  askCleanup: () => void
  /** Called with the word typed into the cleanup dialog. */
  cleanUp: (word: string) => void
  measureStorage: () => void
}

export function AccountsPane(ui: ElementTable, model: PaneModel, actions: PaneActions) {
  const { Box } = ui
  const { m, bodyColumns, header, dialog, focused } = model
  const cancel = { label: m.cancel, onPress: actions.dismiss }
  if (dialog?.kind === 'webhook' && model.webhook) {
    const { draft, templatePath, preview, urlProblem, lastSend } = model.webhook

    return WebhookDialog(ui, { draft, templatePath, preview, urlProblem, lastSend, now: model.now, hasField: model.hasField, m, bodyColumns, header, focused }, actions.webhook)
  }
  if (dialog?.kind === 'period') {
    return ChoiceDialog(
      ui,
      bodyColumns,
      header,
      m.usagePeriodTitle,
      USAGE_PERIODS.map(days => ({ key: `period-${days}`, label: m.usagePeriod(days), isCurrent: days === model.usage.period, onPress: () => actions.setPeriod(days) })),
      cancel,
      focused,
    )
  }
  if (dialog?.kind === 'cleanupDays') {
    return ChoiceDialog(
      ui,
      bodyColumns,
      header,
      m.cleanupDaysTitle,
      CLEANUP_DAYS.map(days => ({ key: `cleanup-days-${days}`, label: m.cleanupDays(days), isCurrent: days === model.storage.cleanupDays, onPress: () => actions.setCleanupDays(days) })),
      cancel,
      focused,
    )
  }
  if (dialog?.kind === 'cleanup') {
    const { asked, cleanupDays } = model.storage

    // Deleting sessions cannot be undone, so the word has to be typed, not a button pressed.
    return InputDialog(
      ui,
      bodyColumns,
      header,
      m.cleanupTitle(asked.count, byteSize(asked.bytes)),
      [{ text: m.cleanupWhat(cleanupDays) }, { text: m.cleanupKeeps, tone: 'muted' }, { text: m.cleanupNoResume, tone: 'danger' }, { text: m.cleanupTypeHint(m.cleanupWord) }],
      {
        key: 'cleanup-word',
        placeholder: m.cleanupPlaceholder(m.cleanupWord),
        submitLabel: m.cleanupConfirm,
        hasField: model.hasField,
        noInput: m.cleanupNoField,
        onSubmit: actions.cleanUp,
      },
      cancel,
      focused,
    )
  }
  const switching = dialog?.kind === 'switch' ? model.accounts.find(one => one.uuid === dialog.uuid) : undefined
  if (switching) {
    // With Orca writing the Claude login here, the switch selects the account in Orca too.
    const lines: DialogLine[] = [{ text: m.switchHint, tone: 'muted' }, ...(model.isOrcaSelecting ? [{ text: m.switchOrcaHint, tone: 'muted' } as const] : [])]

    // Cancel holds the keyboard first: an Enter meant for the prompt never switches every session's login.
    return Dialog(ui, bodyColumns, header, m.switchTitle(switching.email), lines, { label: m.switchButton, onPress: () => actions.switchTo(switching.uuid) }, cancel, focused, 'cancel')
  }
  const removing = dialog?.kind === 'remove' ? model.accounts.find(one => one.uuid === dialog.uuid) : undefined
  if (removing) {
    return Dialog(
      ui,
      bodyColumns,
      header,
      m.removeTitle(removing.email),
      [{ text: m.removeHint, tone: 'muted' }],
      { label: m.removeConfirm, onPress: () => actions.remove(removing.uuid) },
      cancel,
      focused,
      'cancel',
    )
  }

  const tabs = [
    { key: 'accounts', label: m.tabAccounts, hotkey: '1', badge: model.accounts.length > 0 ? `${model.accounts.length}` : undefined },
    { key: 'usage', label: m.tabUsage, hotkey: '2' },
    { key: 'storage', label: m.tabStorage, hotkey: '3' },
  ]
  const select = (key: string) => actions.selectTab(key as AccountsTabKey)
  if (model.tab === 'storage') {
    return (
      <Box flexDirection="column">
        {Header(ui, header)}
        {TabBar(ui, tabs, model.tab, select)}
        <Box key="body-storage" flexDirection="column" marginTop={1}>
          {StorageTab(
            ui,
            { storage: model.storage.view, cleanupDays: model.storage.cleanupDays, now: model.now, locale: model.locale, m, bodyColumns },
            { chooseDays: actions.chooseCleanupDays, cleanUp: actions.askCleanup },
          )}
        </Box>
        {Tiles(ui, bodyColumns, [{ key: 'refresh', label: m.refreshButton, isMain: true, onPress: actions.measureStorage }])}
      </Box>
    )
  }
  if (model.tab === 'usage') {
    return (
      <Box flexDirection="column">
        {Header(ui, header)}
        {TabBar(ui, tabs, model.tab, select)}
        <Box key="body-usage" flexDirection="column" marginTop={1}>
          {UsageTab(ui, { ...model.usage, m, bodyColumns }, { choosePeriod: actions.choosePeriod })}
        </Box>
        {Tiles(ui, bodyColumns, [{ key: 'refresh', label: model.usage.scan ? m.refreshingButton : m.refreshButton, isMain: true, onPress: actions.countUsage }])}
      </Box>
    )
  }

  return (
    <Box flexDirection="column">
      {Header(ui, header)}
      {TabBar(ui, tabs, model.tab, select)}
      {AccountsTab(
        ui,
        {
          list: model.accounts,
          liveUuid: model.liveUuid,
          sessionUuid: model.sessionUuid,
          readings: model.readings,
          codex: model.codex,
          isGuideShown: model.isGuideShown,
          now: model.now,
          locale: model.locale,
          m,
          bodyColumns,
        },
        // Switching changes every session's login, so it asks first, Cancel holding the keyboard.
        { switchTo: actions.askSwitch, remove: actions.askRemove },
      )}
      {Tiles(ui, bodyColumns, [
        { key: 'refresh', label: model.isRefreshing ? m.refreshingButton : m.refreshButton, isMain: true, onPress: actions.refresh },
        { key: 'add', label: m.addButton, onPress: actions.toggleGuide },
        { key: 'webhook', label: m.webhookButton, onPress: actions.openWebhook },
      ])}
    </Box>
  )
}

files.hooks/keychain.ts:
/** The keychain item Claude Code reads its login from, with its default config directory. */
export const LIVE_SERVICE = 'Claude Code-credentials'

/** The environment variables that decide where Claude Code keeps its login. */
export type StorageVariables = { configDir?: string; secureStorageDir?: string }

/**
 * The keychain service Claude Code keeps its login under, named as it names
 * it: `Claude Code-credentials`, then `-` and the first eight hex digits of
 * the SHA-256 of a folder when `CLAUDE_SECURESTORAGE_CONFIG_DIR` names one,
 * or else when `CLAUDE_CONFIG_DIR` is set (that folder, as given, NFC). An
 * empty `CLAUDE_SECURESTORAGE_CONFIG_DIR` keeps the plain name.
 */
export async function liveServiceName(variables: StorageVariables, defaultConfigDir: string): Promise<string> {
  const { secureStorageDir, configDir } = variables
  const isPlain = secureStorageDir !== undefined ? secureStorageDir === '' : !configDir
  if (isPlain) return LIVE_SERVICE
  const folder = (secureStorageDir ?? configDir ?? defaultConfigDir).normalize('NFC')
  const digest = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(folder))
  const hex = Array.from(new Uint8Array(digest), byte => byte.toString(16).padStart(2, '0')).join('')

  return `${LIVE_SERVICE}-${hex.slice(0, 8)}`
}

/** The folder Claude Code keeps `.credentials.json` in: `CLAUDE_SECURESTORAGE_CONFIG_DIR` when set (empty means the default), else its config directory. */
export function credentialsDirectory(variables: StorageVariables, defaultConfigDir: string): string {
  if (variables.secureStorageDir !== undefined) return (variables.secureStorageDir || defaultConfigDir).normalize('NFC')

  return (variables.configDir || defaultConfigDir).normalize('NFC')
}

/** The keychain account Claude Code reads its login with: the user's name, or `claude-code-user` when that holds other characters. */
export function keychainAccountName(user: string | undefined): string {
  return user && /^[a-zA-Z0-9._-]+$/.test(user) ? user : 'claude-code-user'
}
/** The keychain service this mod keeps one item per saved account under. */
export const VAULT_SERVICE = 'account-switch'
/** The keychain service Orca keeps each Claude account's login under, the account named by Orca's account id. */
export const ORCA_COPY_SERVICE = 'Orca Claude Code Managed Credentials'
/** `security`'s exit code for an item that is not there. */
export const ITEM_NOT_FOUND = 44

/** The OAuth credential document Claude Code stores, kept whole. */
export type Credential = {
  claudeAiOauth: {
    accessToken: string
    refreshToken: string
    expiresAt: number
    scopes?: string[]
    subscriptionType?: string
    rateLimitTier?: string
    [field: string]: unknown
  }
  [field: string]: unknown
}

export class KeychainError extends Error {}

/**
 * Whether an account id is one this mod files a login under: letters, digits,
 * `-` and `_`, as a UUID is. It names a keychain item and a vault file, and
 * travels inside a `security -i` line, so nothing else may reach those.
 */
export function isAccountId(id: unknown): id is string {
  return typeof id === 'string' && /^[A-Za-z0-9_-]{1,64}$/.test(id)
}

function toHex(text: string): string {
  return Array.from(new TextEncoder().encode(text), byte => byte.toString(16).padStart(2, '0')).join('')
}

export function parseCredential(text: string): Credential {
  const parsed: unknown = JSON.parse(text.trim())
  const oauth = (parsed as Credential | null)?.claudeAiOauth
  if (typeof oauth?.accessToken !== 'string' || typeof oauth.refreshToken !== 'string') {
    throw new KeychainError('keychain item holds no Claude OAuth credential')
  }

  return parsed as Credential
}

/** argv printing one item's secret. */
export function findArgv(service: string, account?: string): string[] {
  return ['security', 'find-generic-password', '-s', service, ...(account ? ['-a', account] : []), '-w']
}

/**
 * The `security -i` line that creates or replaces an item. The secret travels
 * on stdin as hex, never in argv, the way Claude Code writes its own item.
 */
export function addLine(service: string, account: string, text: string): string {
  // `security -i` reads the line as a command line of its own: a quote, a backslash or a line break would end it.
  for (const value of [service, account]) {
    if (/["\\\n\r]/.test(value)) throw new KeychainError(`refused a keychain name with a quote, backslash or line break: ${JSON.stringify(value)}`)
  }

  return `add-generic-password -U -a "${account}" -s "${service}" -X "${toHex(text)}"\n`
}

export function deleteArgv(service: string, account: string): string[] {
  return ['security', 'delete-generic-password', '-s', service, '-a', account]
}

/**
 * Whether a login is an older copy than the one saved for its account: another
 * grant (refresh token) that expires sooner. Filing it would replace a newer
 * grant with one whose refresh token may already be spent.
 */
export function isOlderGrant(candidate: Credential, saved: Credential | null): boolean {
  if (saved === null) return false

  return candidate.claudeAiOauth.refreshToken !== saved.claudeAiOauth.refreshToken && candidate.claudeAiOauth.expiresAt < saved.claudeAiOauth.expiresAt
}

/** Whether two logins are one grant: the same refresh token, whatever access token each holds now. */
export function isSameGrant(a: Credential | null, b: Credential | null): boolean {
  return a !== null && b !== null && a.claudeAiOauth.refreshToken === b.claudeAiOauth.refreshToken
}

/**
 * Whether `.credentials.json` holds an older login than the keychain: another
 * token there, expiring no later. Claude Code refreshes into the keychain
 * alone, while a session with that file drops its cached login only when the
 * file changes, so a file left behind keeps every other session on a token
 * whose refresh token is already spent, and it expires with "Login expired".
 */
export function fileLagsKeychain(file: Credential | null, keychain: Credential): boolean {
  if (file === null) return false

  return file.claudeAiOauth.accessToken !== keychain.claudeAiOauth.accessToken && file.claudeAiOauth.expiresAt <= keychain.claudeAiOauth.expiresAt
}

files.hooks/lock.ts:
import type { Io } from './io'
import { encodePowerShell, powerShellLiteral } from './shared/files'

/**
 * Locks held across processes, laid out as proper-lockfile (Claude Code's own
 * locks) lays them: a directory that only one process can make, taken as
 * abandoned once its modification time is older than the lock's stale time.
 * Taking Claude Code's lock before writing a file it guards keeps the write
 * from landing between its read and its write.
 */

/** A lock this process holds. */
export type Lock = {
  /** Gives the lock up; a lock already taken over as stale is left alone. */
  release: () => Promise<void>
  /** Marks the lock alive, for work that holds it longer than half its stale time. */
  touch: () => Promise<void>
}

export class LockBusyError extends Error {}

export type LockOptions = {
  /** How old the lock's time may grow before another process takes it as abandoned. */
  staleMs: number
  /** How many times to try before giving up, waiting longer each time. */
  tries: number
  isWindows: boolean
}

/** The waits between tries: 100 ms, doubling, at most a second. */
export function retryDelay(attempt: number): number {
  return Math.min(1000, 100 * 2 ** attempt)
}

/** argv making the lock directory, its parent first; it fails when the directory is there. */
export function makeLockArgv(path: string, isWindows: boolean): string[] {
  if (!isWindows) return ['/bin/sh', '-c', 'mkdir -p "$(dirname "$0")" && mkdir "$0"', path]
  const script = `$p = ${powerShellLiteral(path)}; if (Test-Path -LiteralPath $p) { exit 1 }; New-Item -ItemType Directory -Force -Path (Split-Path -LiteralPath $p) | Out-Null; try { New-Item -ItemType Directory -Path $p -ErrorAction Stop | Out-Null } catch { exit 1 }`

  return ['powershell.exe', '-NoProfile', '-NonInteractive', '-EncodedCommand', encodePowerShell(script)]
}

/** argv removing the lock directory, empty as a lock is; absent is fine. */
export function removeLockArgv(path: string, isWindows: boolean): string[] {
  if (!isWindows) return ['/bin/sh', '-c', '[ ! -d "$0" ] || rmdir "$0"', path]
  const script = `$p = ${powerShellLiteral(path)}; if (Test-Path -LiteralPath $p) { Remove-Item -LiteralPath $p -Force -ErrorAction Stop }`

  return ['powershell.exe', '-NoProfile', '-NonInteractive', '-EncodedCommand', encodePowerShell(script)]
}

/** argv setting the lock directory's time to now. */
export function touchLockArgv(path: string, isWindows: boolean): string[] {
  if (!isWindows) return ['touch', path]
  const script = `(Get-Item -LiteralPath ${powerShellLiteral(path)}).LastWriteTime = Get-Date`

  return ['powershell.exe', '-NoProfile', '-NonInteractive', '-EncodedCommand', encodePowerShell(script)]
}

/** Takes the lock at `path`, taking over one abandoned past its stale time; `LockBusyError` when it stays held. */
export async function acquire(io: Io, path: string, options: LockOptions): Promise<Lock> {
  for (let attempt = 0; attempt < options.tries; attempt += 1) {
    const made = await io.run(makeLockArgv(path, options.isWindows), { timeoutMs: 10_000 })
    if (made.exitCode === 0) {
      let mtimeMs = (await io.stat(path).catch(() => null))?.mtimeMs ?? 0

      return {
        release: async () => {
          // Taken over as stale and made again by another process: that lock is not this one's to remove.
          const now = (await io.stat(path).catch(() => null))?.mtimeMs
          if (now === undefined || now !== mtimeMs) return
          await io.run(removeLockArgv(path, options.isWindows), { timeoutMs: 10_000 })
        },
        touch: async () => {
          await io.run(touchLockArgv(path, options.isWindows), { timeoutMs: 10_000 })
          mtimeMs = (await io.stat(path).catch(() => null))?.mtimeMs ?? mtimeMs
        },
      }
    }
    const held = await io.stat(path).catch(() => null)
    // Made by nobody yet the directory could not be made: not a lock held but a failure to report.
    if (held === null) throw new Error(`cannot make the lock ${path}: ${made.stderr.trim()}`)
    if ((await io.now()) - held.mtimeMs > options.staleMs) {
      // Removed only while it is still the abandoned one seen: another process may have just taken it over.
      if ((await io.stat(path).catch(() => null))?.mtimeMs === held.mtimeMs) await io.run(removeLockArgv(path, options.isWindows), { timeoutMs: 10_000 })
      continue
    }
    if (attempt + 1 < options.tries) await io.sleep(retryDelay(attempt))
  }

  throw new LockBusyError(`the lock ${path} is held by another process`)
}

/** Runs `work` holding the lock at `path`, and gives the lock up after, whatever `work` did. */
export async function withLock<T>(io: Io, path: string, options: LockOptions, work: (lock: Lock) => Promise<T>): Promise<T> {
  const lock = await acquire(io, path, options)
  try {
    return await work(lock)
  } finally {
    await lock.release().catch((error: unknown) => io.log(`cannot release ${path}: ${error instanceof Error ? error.message : String(error)}`))
  }
}

files.hooks/orca.ts:
/**
 * Orca keeps Claude logins of its own. While one of them is selected there,
 * Orca writes it into Claude Code's login (the keychain items, the credentials
 * file and `oauthAccount` in `~/.claude.json`) each time it launches Claude,
 * fetches the rate limits or starts, so a login changed anywhere else is put
 * back at Orca's next write. A switch therefore selects the account in Orca
 * too, and a login Orca keeps a copy of is never refreshed here: refreshing it
 * would spend the refresh token Orca's copy holds.
 *
 * These helpers read what Orca says and build what is sent to it; the hooks
 * module talks to Orca's runtime through them where its `orca-runtime.json`
 * says, as Orca's own CLI does: its Unix socket through `perl` on macOS and
 * Linux, its named pipe through PowerShell on Windows.
 */

/** A Claude account Orca keeps. */
export type OrcaAccount = { id: string; email: string; organizationUuid: string | null }

/** Orca's Claude logins: the accounts it keeps, and the one it writes into Claude Code (null when it leaves the login alone). */
export type OrcaClaude = { accounts: OrcaAccount[]; activeId: string | null }

/** Where Orca's running app answers, from the `orca-runtime.json` it writes: a Unix socket, or a named pipe on Windows. */
export type OrcaRuntime = { endpoint: string; authToken: string }

/** How Orca's runtime is reached on a platform: its Unix socket, or on Windows its named pipe. */
export type OrcaTransport = 'unix' | 'named-pipe'

/** What came of asking Orca: not installed, installed but not running, running but not answering, or its answer. */
export type OrcaReach = { kind: 'absent' } | { kind: 'down' } | { kind: 'unreachable'; reason: string } | { kind: 'ok'; claude: OrcaClaude }

/** The file in Orca's data folder that names its runtime's endpoint (a socket, or a named pipe on Windows) and token. */
export const ORCA_RUNTIME_FILE = 'orca-runtime.json'

/** How long a selection asked while Orca was closed waits for Orca to run again. */
export const ORCA_PENDING_KEPT_MS = 7 * 24 * 60 * 60 * 1000

/**
 * Orca's data folder, found as Orca's CLI finds it: `ORCA_USER_DATA_PATH`
 * (set in Orca's own terminals), else the platform's application data folder;
 * null on Windows without `APPDATA`.
 */
export function orcaDataDirectory(place: { userDataVariable?: string; home: string; isMac: boolean; isWindows: boolean; xdgConfigHome?: string; appData?: string }): string | null {
  if (place.userDataVariable) return place.userDataVariable
  if (place.isWindows) return place.appData ? `${place.appData.replaceAll('\\', '/')}/orca` : null
  if (place.isMac) return `${place.home}/Library/Application Support/orca`

  return `${place.xdgConfigHome || `${place.home}/.config`}/orca`
}

/** The runtime's endpoint for the transport this platform uses, and its token, from `orca-runtime.json`; null when it names neither. */
export function parseOrcaRuntime(text: string, transport: OrcaTransport): OrcaRuntime | null {
  let metadata: { transports?: unknown; authToken?: unknown }
  try {
    metadata = JSON.parse(text) as { transports?: unknown; authToken?: unknown }
  } catch (error) {
    if (error instanceof SyntaxError) return null
    throw error
  }
  if (typeof metadata.authToken !== 'string' || metadata.authToken === '' || !Array.isArray(metadata.transports)) return null
  const found = (metadata.transports as { kind?: unknown; endpoint?: unknown }[]).find(one => one.kind === transport && typeof one.endpoint === 'string' && one.endpoint !== '')

  return found ? { endpoint: found.endpoint as string, authToken: metadata.authToken } : null
}

/** One request to Orca's runtime as a line of JSON; it carries the token, so it goes on stdin, never in argv. */
export function orcaRequestLine(id: string, authToken: string, method: string, params?: unknown): string {
  return `${JSON.stringify(params === undefined ? { id, authToken, method } : { id, authToken, method, params })}\n`
}

/** Orca's answer to one request: its result, or the reason it gave. */
export type OrcaFrame = { ok: true; result: unknown } | { ok: false; reason: string }

/** The answer in what the runtime sent, keepalive lines skipped; null when no answer to `id` is there. */
export function parseOrcaFrame(text: string, id: string): OrcaFrame | null {
  for (const line of text.split('\n')) {
    if (line.trim() === '') continue
    let frame: { id?: unknown; ok?: unknown; result?: unknown; error?: { message?: unknown } | null; _keepalive?: unknown }
    try {
      frame = JSON.parse(line) as typeof frame
    } catch (error) {
      if (error instanceof SyntaxError) continue
      throw error
    }
    if (frame._keepalive === true || frame.id !== id) continue
    if (frame.ok === true) return { ok: true, result: frame.result }

    return { ok: false, reason: typeof frame.error?.message === 'string' ? frame.error.message : 'Orca refused the request' }
  }

  return null
}

/** The Claude part of what `accounts.list` answers, or null when it holds none. */
export function parseOrcaClaude(result: unknown): OrcaClaude | null {
  const claude = (result as { claude?: { accounts?: unknown; activeAccountId?: unknown; activeAccountIdsByRuntime?: { host?: unknown } } } | null)?.claude
  if (!claude || !Array.isArray(claude.accounts)) return null
  const accounts = (claude.accounts as { id?: unknown; email?: unknown; organizationUuid?: unknown; managedAuthRuntime?: unknown }[])
    // A login Orca keeps in a WSL distribution is written there, not into this machine's Claude Code.
    .filter(account => typeof account.id === 'string' && typeof account.email === 'string' && (account.managedAuthRuntime ?? 'host') === 'host')
    .map(account => ({
      id: account.id as string,
      email: account.email as string,
      organizationUuid: typeof account.organizationUuid === 'string' && account.organizationUuid !== '' ? account.organizationUuid : null,
    }))
  const host = claude.activeAccountIdsByRuntime?.host
  const active = host === undefined ? claude.activeAccountId : host
  const activeId = typeof active === 'string' && accounts.some(account => account.id === active) ? active : null

  return { accounts, activeId }
}

/**
 * The account Orca keeps for a login, matched as Orca matches its own: the
 * same email, ignoring case, and the same organization. Without the
 * organization the email decides, when only one account holds it.
 */
export function orcaAccountFor(claude: OrcaClaude, email: string, organizationUuid?: string | null): OrcaAccount | undefined {
  const sameEmail = claude.accounts.filter(account => account.email.trim().toLowerCase() === email.trim().toLowerCase())
  if (organizationUuid) return sameEmail.find(account => account.organizationUuid === organizationUuid)

  return sameEmail.length === 1 ? sameEmail[0] : undefined
}

/** The email of the account Orca writes into Claude Code, or null when it leaves the login alone. */
export function orcaActiveEmail(claude: OrcaClaude | null): string | null {
  return claude?.accounts.find(account => account.id === claude.activeId)?.email ?? null
}

/**
 * How a switch to an account goes with Orca as it stands:
 * - `direct`: Orca is not installed, or leaves Claude Code's login alone;
 * - `select`: Orca runs and keeps the account, so it is selected there too;
 * - `refuse`: Orca runs, writes another login and keeps none for this account, so it would put its own back;
 * - `pending`: Orca keeps the account but does not run now; it is selected once Orca answers again;
 * - `warn`: Orca does not run now and keeps no login for the account; it puts its own back when it starts.
 *
 * `remembered` is what Orca said last, for when it does not answer now.
 */
export type OrcaPlan =
  | { kind: 'direct' }
  | { kind: 'select'; account: OrcaAccount; activeId: string | null }
  | { kind: 'refuse'; activeEmail: string | null }
  | { kind: 'pending'; account: OrcaAccount; activeId: string | null }
  | { kind: 'warn'; activeEmail: string | null }

export function planSwitch(reach: OrcaReach, remembered: OrcaClaude | null, email: string, organizationUuid?: string | null): OrcaPlan {
  if (reach.kind === 'absent') return { kind: 'direct' }
  if (reach.kind === 'ok') {
    if (reach.claude.activeId === null) return { kind: 'direct' }
    const account = orcaAccountFor(reach.claude, email, organizationUuid)

    return account ? { kind: 'select', account, activeId: reach.claude.activeId } : { kind: 'refuse', activeEmail: orcaActiveEmail(reach.claude) }
  }
  if (!remembered || remembered.activeId === null) return { kind: 'direct' }
  const account = orcaAccountFor(remembered, email, organizationUuid)

  return account ? { kind: 'pending', account, activeId: remembered.activeId } : { kind: 'warn', activeEmail: orcaActiveEmail(remembered) }
}

/**
 * What a change of the login, made by no switch of this mod, means with Orca:
 * - `none`: Orca is not there, or leaves Claude Code's login alone;
 * - `orca`: the login is now the account Orca writes, so Orca made the change;
 * - `follow`: the login is an account Orca keeps but does not write, so Orca is told to write it, or it would put its own back;
 * - `revert`: the login is an account Orca keeps no copy of; Orca puts its own back at its next write.
 */
export type OrcaFollow = { kind: 'none' } | { kind: 'orca' } | { kind: 'follow'; account: OrcaAccount } | { kind: 'revert'; activeEmail: string | null }

export function planFollow(claude: OrcaClaude | null, email: string, organizationUuid?: string | null): OrcaFollow {
  if (!claude || claude.activeId === null) return { kind: 'none' }
  const account = orcaAccountFor(claude, email, organizationUuid)
  if (account?.id === claude.activeId) return { kind: 'orca' }

  return account ? { kind: 'follow', account } : { kind: 'revert', activeEmail: orcaActiveEmail(claude) }
}

/**
 * Whether Orca keeps a copy of this login, selected or not: refreshing the
 * token here would spend the refresh token that copy holds, and Orca would
 * later write a spent login into Claude Code.
 */
export function isKeptByOrca(claude: OrcaClaude | null, email: string, organizationUuid?: string | null): boolean {
  return claude !== null && orcaAccountFor(claude, email, organizationUuid) !== undefined
}

/** A selection asked while Orca was not running: the account, and the one Orca wrote then. */
export type OrcaPending = { accountId: string; email: string; activeBefore: string | null; at: number }

/**
 * What to do with a pending selection now that Orca answers: `apply` it;
 * `done` when Orca already writes that account; `drop` it when it is a week
 * old, Orca no longer keeps the account, or someone picked another account in
 * Orca since (Orca writes neither the account then nor the one asked).
 */
export function pendingStep(pending: OrcaPending, claude: OrcaClaude, now: number): 'apply' | 'done' | 'drop' {
  if (claude.activeId === pending.accountId) return 'done'
  if (now - pending.at > ORCA_PENDING_KEPT_MS) return 'drop'
  if (!claude.accounts.some(account => account.id === pending.accountId)) return 'drop'

  return claude.activeId === pending.activeBefore ? 'apply' : 'drop'
}

/** Reads a pending selection kept in the store, or null. */
export function asPending(value: unknown): OrcaPending | null {
  const pending = value as Partial<OrcaPending> | null | undefined
  if (!pending || typeof pending.accountId !== 'string' || typeof pending.email !== 'string' || typeof pending.at !== 'number') return null

  return { accountId: pending.accountId, email: pending.email, activeBefore: typeof pending.activeBefore === 'string' ? pending.activeBefore : null, at: pending.at }
}

/** Reads what Orca said last, kept in the store as `{ claude: OrcaClaude }`, or null. */
export function asRemembered(value: unknown): OrcaClaude | null {
  const claude = (value as { claude?: { accounts?: unknown; activeId?: unknown } } | null | undefined)?.claude
  if (!claude || !Array.isArray(claude.accounts)) return null
  const accounts = (claude.accounts as Partial<OrcaAccount>[])
    .filter(account => typeof account.id === 'string' && typeof account.email === 'string')
    .map(account => ({ id: account.id as string, email: account.email as string, organizationUuid: typeof account.organizationUuid === 'string' ? account.organizationUuid : null }))
  const activeId = typeof claude.activeId === 'string' && accounts.some(account => account.id === claude.activeId) ? claude.activeId : null

  return { accounts, activeId }
}

/** How the clients below end: 0 printed an answer; the rest say why there is none. */
export const ORCA_EXIT = { answered: 0, cannotConnect: 2, timedOut: 3, closed: 4, cannotSend: 5 } as const

/** The pipe's name as .NET takes it: the endpoint without its `\\.\pipe\` prefix. */
export function pipeName(endpoint: string): string {
  return endpoint.replace(/^\\\\\.\\pipe\\/i, '').replace(/^\/\/\.\/pipe\//i, '')
}

/**
 * A client for Orca's runtime on Windows, as a PowerShell script: it connects
 * to the named pipe, sends the request line it reads from stdin, and prints the
 * first line back that is not a keepalive, within `seconds`. Its exit codes
 * are those of the Perl client.
 */
export function orcaPipeScript(endpoint: string, seconds: number): string {
  const name = pipeName(endpoint).replace(/'/g, "''")

  return [
    "$ErrorActionPreference = 'Stop'",
    '$utf8 = New-Object System.Text.UTF8Encoding($false)',
    `$pipe = New-Object System.IO.Pipes.NamedPipeClientStream('.', '${name}', [System.IO.Pipes.PipeDirection]::InOut)`,
    `try { $pipe.Connect(${Math.min(seconds, 5) * 1000}) } catch { [Console]::Error.WriteLine($_.Exception.Message); exit ${ORCA_EXIT.cannotConnect} }`,
    '$reader = New-Object System.IO.StreamReader($pipe, $utf8)',
    '$writer = New-Object System.IO.StreamWriter($pipe, $utf8)',
    '$writer.AutoFlush = $true',
    '$request = [Console]::In.ReadToEnd()',
    'if (-not $request.EndsWith("`n")) { $request += "`n" }',
    `try { $writer.Write($request) } catch { [Console]::Error.WriteLine($_.Exception.Message); exit ${ORCA_EXIT.cannotSend} }`,
    `$deadline = [DateTime]::UtcNow.AddSeconds(${seconds})`,
    'while ($true) {',
    '  $task = $reader.ReadLineAsync()',
    '  $left = ($deadline - [DateTime]::UtcNow).TotalMilliseconds',
    `  if ($left -le 0 -or -not $task.Wait([int]$left)) { [Console]::Error.WriteLine('timed out'); exit ${ORCA_EXIT.timedOut} }`,
    '  $line = $task.Result',
    `  if ($null -eq $line) { [Console]::Error.WriteLine('closed'); exit ${ORCA_EXIT.closed} }`,
    '  if ($line.Trim() -eq \'\' -or $line -match \'^\\s*\\{\\s*"_keepalive"\\s*:\\s*true\\s*\\}\\s*$\') { continue }',
    '  [Console]::Out.WriteLine($line)',
    `  exit ${ORCA_EXIT.answered}`,
    '}',
  ].join('\n')
}

/**
 * A client for Orca's runtime in Perl, which macOS and Linux both carry: it
 * connects to the socket in its first argument, sends the request line it
 * reads from stdin, and prints the first line back that is not a keepalive,
 * within the seconds in its second argument.
 */
export const ORCA_CLIENT_SCRIPT = [
  'use strict; use warnings; use IO::Socket::UNIX; use Socket qw(SOCK_STREAM);',
  `$SIG{ALRM} = sub { print STDERR "timed out\\n"; exit ${ORCA_EXIT.timedOut} };`,
  'alarm($ARGV[1]);',
  `my $socket = IO::Socket::UNIX->new(Type => SOCK_STREAM, Peer => $ARGV[0]) or do { print STDERR "$!\\n"; exit ${ORCA_EXIT.cannotConnect} };`,
  'my $request = do { local $/; <STDIN> };',
  `print {$socket} $request or do { print STDERR "$!\\n"; exit ${ORCA_EXIT.cannotSend} };`,
  '$socket->flush;',
  'while (defined(my $line = <$socket>)) {',
  '  next if $line =~ /^\\s*$/ || $line =~ /^\\s*\\{\\s*"_keepalive"\\s*:\\s*true\\s*\\}\\s*$/;',
  '  print $line;',
  `  exit ${ORCA_EXIT.answered};`,
  '}',
  `print STDERR "closed\\n"; exit ${ORCA_EXIT.closed};`,
].join('\n')

