// Copied from shared/ by scripts/sync.mjs; edit shared/ and run the script.
/** Terminal layout: gauges and their colours, cell widths, and packing cells into rows. */

/** A thin bar of `width` cells, in its filled and remaining parts, so each takes its own color. */
export function barParts(percent: number, width = 8): { filled: string; rest: string } {
  const cells = Math.round((Math.min(100, Math.max(0, percent)) / 100) * width)

  return { filled: '━'.repeat(cells), rest: '━'.repeat(width - cells) }
}

/** The bar as one string: what its cells measure. */
export function bar(percent: number, width = 8): string {
  const { filled, rest } = barParts(percent, width)

  return filled + rest
}

export function severityColor(percent: number): string {
  if (percent >= 90) return 'red'
  if (percent >= 70) return 'yellow'

  return 'green'
}

/**
 * Characters a terminal draws over the cell before them: combining marks,
 * Hangul's vowel and final jamo (a decomposed syllable is one wide cell),
 * zero-width spaces and joiners, and variation selectors.
 */
function isZeroWidth(code: number): boolean {
  return (
    (code >= 0x0300 && code <= 0x036f) ||
    (code >= 0x1160 && code <= 0x11ff) ||
    (code >= 0x1ab0 && code <= 0x1aff) ||
    (code >= 0x1dc0 && code <= 0x1dff) ||
    (code >= 0x200b && code <= 0x200f) ||
    (code >= 0x2060 && code <= 0x2064) ||
    (code >= 0x20d0 && code <= 0x20ff) ||
    (code >= 0xd7b0 && code <= 0xd7ff) ||
    (code >= 0xfe00 && code <= 0xfe0f) ||
    (code >= 0xfe20 && code <= 0xfe2f) ||
    code === 0xfeff ||
    (code >= 0xe0100 && code <= 0xe01ef)
  )
}

/** East Asian wide and fullwidth characters, and emoji drawn as pictures: two cells. */
function isWide(code: number): boolean {
  return (
    (code >= 0x1100 && code <= 0x115f) ||
    (code >= 0x2e80 && code <= 0xa4cf) ||
    (code >= 0xa960 && code <= 0xa97f) ||
    (code >= 0xac00 && code <= 0xd7a3) ||
    (code >= 0xf900 && code <= 0xfaff) ||
    (code >= 0xfe30 && code <= 0xfe4f) ||
    (code >= 0xff00 && code <= 0xff60) ||
    (code >= 0xffe0 && code <= 0xffe6) ||
    (code >= 0x1f300 && code <= 0x1f64f) ||
    (code >= 0x1f680 && code <= 0x1f6ff) ||
    (code >= 0x1f900 && code <= 0x1f9ff) ||
    (code >= 0x1fa70 && code <= 0x1faff) ||
    (code >= 0x20000 && code <= 0x3fffd)
  )
}

/** Terminal cells a string takes: wide characters take two, combining ones none. */
export function displayWidth(text: string): number {
  let width = 0
  for (const char of text) {
    const code = char.codePointAt(0) ?? 0
    width += isZeroWidth(code) ? 0 : isWide(code) ? 2 : 1
  }

  return width
}

/**
 * The escape sequences a program writes for a terminal, each removed whole:
 * CSI (`ESC [`, or its one-byte form) with its parameters and final byte; OSC,
 * DCS, SOS, PM and APC strings up to their terminator; and the short escapes,
 * such as `ESC ( B` from `tput sgr0` and `ESC 7` saving the cursor.
 */
const ESCAPE_SEQUENCE =
  /(?:\u001b\[|\u009b)[0-?]*[ -/]*[@-~]|(?:\u001b[\]PX^_]|[\u0090\u0098\u009d-\u009f])[^\u0007\u001b\u009c]*(?:\u0007|\u001b\\|\u009c)?|\u001b[ -/]*[0-~]/g
/** Every control character but tab and newline: C0, DEL and C1. */
const CONTROL = /[\u0000-\u0008\u000b-\u001f\u007f-\u009f]/g

/**
 * Text from outside the plugin (a file, a prompt, a model's answer, a
 * program's output) as it may be drawn: its escape sequences and control
 * characters removed, tab and newline kept. The engine refuses a whole tree
 * whose text, label, input value or code holds one, and draws the pane blank.
 */
export function printable(text: string): string {
  return text.replace(ESCAPE_SEQUENCE, '').replace(CONTROL, '')
}

/**
 * Splits items into rows no wider than `room`, `gap` cells apart, in order;
 * an item wider than `room` gets a row to itself.
 */
export function packRows<T extends { width: number }>(items: T[], room: number, gap: number): T[][] {
  const rows: T[][] = []
  let used = 0
  for (const item of items) {
    const row = rows[rows.length - 1]
    if (row && used + gap + item.width <= room) {
      row.push(item)
      used += gap + item.width
    } else {
      rows.push([item])
      used = item.width
    }
  }

  return rows
}

/**
 * `text` cut to `width` terminal cells, an ellipsis marking the cut. Counts
 * East Asian wide characters as two cells, so a Korean label never overflows
 * the room it was given.
 */
export function truncate(text: string, width: number): string {
  if (displayWidth(text) <= width) return text
  if (width <= 1) return width === 1 ? '…' : ''
  let out = ''
  let used = 0
  for (const char of text) {
    const cells = displayWidth(char)
    if (used + cells > width - 1) break
    out += char
    used += cells
  }

  return `${out}…`
}

/** `text` padded with spaces to `width` terminal cells, on the start or the end side. */
export function padCells(text: string, width: number, side: 'start' | 'end' = 'end'): string {
  const fill = ' '.repeat(Math.max(0, width - displayWidth(text)))

  return side === 'start' ? fill + text : text + fill
}

files.hooks/shared/files.ts:
// Copied from shared/ by scripts/sync.mjs; edit shared/ and run the script.
/**
 * Deleting files by argv on every platform, with no shell to read the paths.
 *
 * Claude Code starts a plugin's command without a shell. On a POSIX system
 * `rm -f -- <paths>` takes each path as one argument. Windows has no `rm`,
 * and `cmd.exe /c del` would read the paths again by cmd's own rules (`%VAR%`
 * expanded, quotes stripped), so there PowerShell runs `Remove-Item
 * -LiteralPath` from an encoded script: the paths travel inside the script as
 * single-quoted literals and are never parsed as a command line.
 */

/** The script as PowerShell's `-EncodedCommand` takes it: UTF-16LE, then base64. */
export function encodePowerShell(script: string): string {
  let bytes = ''
  for (let index = 0; index < script.length; index += 1) {
    const unit = script.charCodeAt(index)
    bytes += String.fromCharCode(unit & 0xff, unit >> 8)
  }

  return btoa(bytes)
}

/**
 * A path as a PowerShell single-quoted literal: nothing in it is special but
 * a single quote, which PowerShell also reads in its curly forms (‘ ’ ‚ ‛);
 * each is doubled.
 */
export function powerShellLiteral(path: string): string {
  return `'${path.replace(/['\u2018\u2019\u201a\u201b]/g, quote => quote + quote)}'`
}

/** argv deleting `paths`, absent or not; relative paths resolve against the command's working directory. */
export function removeArgv(paths: readonly string[], isWindows: boolean): string[] {
  if (!isWindows) return ['rm', '-f', '--', ...paths]
  // Only files are deleted, and an absent path is passed over: Remove-Item on a directory with
  // children asks whether to go on, a question no plugin answers. A file that cannot be deleted
  // stops the script, which exits 1.
  const script = `foreach ($p in @(${paths.map(powerShellLiteral).join(',')})) { if (Test-Path -LiteralPath $p -PathType Leaf) { Remove-Item -LiteralPath $p -Force -ErrorAction Stop } }`

  return ['powershell.exe', '-NoProfile', '-NonInteractive', '-EncodedCommand', encodePowerShell(script)]
}

/**
 * argv deleting `paths` with everything under them, absent or not: a session's
 * transcript and its folder of subagent transcripts and tool output. The
 * caller checks every path lies where it means to delete; nothing here does.
 */
export function removeTreeArgv(paths: readonly string[], isWindows: boolean): string[] {
  if (!isWindows) return ['rm', '-rf', '--', ...paths]
  // -Recurse with -Force asks nothing: a folder with children is deleted whole.
  const script = `foreach ($p in @(${paths.map(powerShellLiteral).join(',')})) { if (Test-Path -LiteralPath $p) { Remove-Item -LiteralPath $p -Recurse -Force -ErrorAction Stop } }`

  return ['powershell.exe', '-NoProfile', '-NonInteractive', '-EncodedCommand', encodePowerShell(script)]
}

files.hooks/storage.ts:
import type { StorageProject, StorageView } from '../types'

/**
 * What Claude Code keeps on this machine under its config directory, and
 * which sessions a cleanup would delete. Pure: the hooks module walks the
 * folders and deletes; this file only adds up and chooses.
 */

/** A file under the projects folder: its path from there, its size and when it last changed. */
export type StorageFile = { relative: string; size: number; mtimeMs: number }

/** One session's files: its transcript, and its folder of subagent transcripts and tool output. */
export type StorageSession = {
  /** The project folder it is kept in. */
  folder: string
  session: string
  bytes: number
  /** `mtimeMs` of its newest file. */
  lastActive: number
  /** Paths from the projects folder to delete it: the transcript and the session's folder, those that exist. */
  paths: string[]
}

/** What the projects folder holds, by kind and by project; the folders and settings beside it are added by the caller. */
export type StorageSummary = Pick<StorageView, 'bytes' | 'transcripts' | 'subagents' | 'other' | 'sessions'> & { projects: Omit<StorageProject, 'name'>[] }

/** The project folder, the session and whether the path is the session's transcript, from a path under the projects folder. */
function placeOf(relative: string): { folder: string; session: string; isTranscript: boolean } | null {
  const parts = relative.split('/').filter(Boolean)
  if (parts.length < 2) return null
  const [folder = '', second = ''] = parts
  if (parts.length === 2) return second.endsWith('.jsonl') ? { folder, session: second.slice(0, -'.jsonl'.length), isTranscript: true } : null

  return { folder, session: second, isTranscript: false }
}

/** The files grouped by session, each with what deleting it removes. */
export function sessionsOf(files: StorageFile[]): StorageSession[] {
  const byKey = new Map<string, StorageSession & { hasTranscript: boolean; hasFolder: boolean }>()
  for (const file of files) {
    const place = placeOf(file.relative)
    if (!place) continue
    const key = `${place.folder}/${place.session}`
    const known = byKey.get(key) ?? { folder: place.folder, session: place.session, bytes: 0, lastActive: 0, paths: [], hasTranscript: false, hasFolder: false }
    known.bytes += file.size
    known.lastActive = Math.max(known.lastActive, file.mtimeMs)
    if (place.isTranscript) known.hasTranscript = true
    else known.hasFolder = true
    byKey.set(key, known)
  }

  return [...byKey.values()].map(({ hasTranscript, hasFolder, ...session }) => ({
    ...session,
    paths: [...(hasTranscript ? [`${session.folder}/${session.session}.jsonl`] : []), ...(hasFolder ? [`${session.folder}/${session.session}`] : [])],
  }))
}

/** What the projects folder holds, by kind and by project. */
export function summarizeStorage(files: StorageFile[]): StorageSummary {
  const add = (into: { count: number; bytes: number }, size: number) => ({ count: into.count + 1, bytes: into.bytes + size })
  let transcripts = { count: 0, bytes: 0 }
  let subagents = { count: 0, bytes: 0 }
  let other = { count: 0, bytes: 0 }
  for (const file of files) {
    const place = placeOf(file.relative)
    if (place?.isTranscript) transcripts = add(transcripts, file.size)
    else if (file.relative.endsWith('.jsonl') && file.relative.includes('/subagents/')) subagents = add(subagents, file.size)
    else other = add(other, file.size)
  }
  const sessions = sessionsOf(files)
  const byFolder = new Map<string, Omit<StorageProject, 'name'>>()
  for (const session of sessions) {
    const known = byFolder.get(session.folder) ?? { folder: session.folder, bytes: 0, sessions: 0, lastActive: 0 }
    byFolder.set(session.folder, {
      folder: session.folder,
      bytes: known.bytes + session.bytes,
      sessions: known.sessions + 1,
      lastActive: Math.max(known.lastActive, session.lastActive),
    })
  }

  return {
    bytes: transcripts.bytes + subagents.bytes + other.bytes,
    transcripts,
    subagents,
    other,
    sessions: sessions.length,
    projects: [...byFolder.values()].sort((a, b) => b.bytes - a.bytes),
  }
}

/**
 * The sessions a cleanup deletes: every one whose newest file is older than
 * `days` days, but never one of `keep` (the sessions running now).
 */
export function cleanupPlan(sessions: StorageSession[], days: number, now: number, keep: readonly string[]): { sessions: StorageSession[]; bytes: number } {
  const before = now - days * 86_400_000
  const chosen = sessions.filter(session => session.lastActive < before && !keep.includes(session.session))

  return { sessions: chosen, bytes: chosen.reduce((sum, session) => sum + session.bytes, 0) }
}

/**
 * The sessions running Claude Code processes name in their command lines, one
 * process a line: the id after `--resume`, `-r` or `--session-id`. A session
 * resumed in another window but idle past a cleanup's age is still in use.
 */
export function sessionIdsInCommands(commandLines: string): string[] {
  const ids = new Set<string>()
  const id = '([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})'
  for (const line of commandLines.split('\n')) {
    if (!/claude/i.test(line)) continue
    for (const match of line.matchAll(new RegExp(`(?:--resume|--session-id|-r)(?:=|\\s+)${id}`, 'g'))) if (match[1]) ids.add(match[1].toLowerCase())
  }

  return [...ids]
}

/**
 * The sessions a cleanup deletes now: those planned now that the dialog also
 * showed when the person confirmed it. A session that went idle past the age
 * between the two was never asked about, and stays.
 */
export function confirmedSessions(planned: StorageSession[], confirmed: ReadonlySet<string>): StorageSession[] {
  return planned.filter(session => confirmed.has(`${session.folder}/${session.session}`))
}

/** A size in a few characters: `512 B`, `12.4 KB`, `221.6 MB`, `17.0 GB`. */
export function byteSize(bytes: number): string {
  const units: [number, string][] = [
    [1024 ** 3, 'GB'],
    [1024 ** 2, 'MB'],
    [1024, 'KB'],
  ]
  for (const [size, unit] of units) if (bytes >= size) return `${(bytes / size).toFixed(1)} ${unit}`

  return `${bytes} B`
}

/**
 * The absolute paths a cleanup deletes, each under `root`; throws, deleting
 * nothing, when one would reach outside it (an absolute part, `.` or `..`).
 */
export function cleanupTargets(root: string, relatives: readonly string[]): string[] {
  return relatives.map(relative => {
    const parts = relative.split(/[\\/]/)
    if (relative === '' || relative.startsWith('/') || /^[A-Za-z]:/.test(relative) || parts.some(part => part === '' || part === '.' || part === '..')) {
      throw new Error(`refused to delete outside ${root}: ${relative}`)
    }

    return `${root}/${relative}`
  })
}

files.hooks/usage.ts:
import type { RankRow, Tokens, UsageSummary } from '../types'

/**
 * Token usage counted from Claude Code's session transcripts on this machine.
 *
 * Each response the model sent is one transcript line with its usage. The
 * lines are read outside the plugin's environment (`sh`, `head`, `tail`,
 * `awk`), only the bytes appended since the last count, and only the fields
 * counted here leave the shell. A response is written once per content
 * block, so its message id is counted once.
 */


/** One response as the scan reads it. */
export type ScanRecord = { at: string; cwd: string; model: string; id: string; input: number; cacheWrite: number; cacheRead: number; output: number }

/** What has been counted, kept in a file of the mod's own between sessions. */
export type UsageIndex = {
  version: 3
  /** Per transcript: the bytes counted so far. */
  files: Record<string, { offset: number }>
  /**
   * Every message id counted, in any transcript: a resumed or forked session
   * copies earlier responses into its own transcript, ids and all, and each is
   * counted once. Kept as a list in the file; a count works on it as a set.
   */
  ids: string[]
  /** Tokens by `day\tmodel\tproject`; the day is the local date. */
  buckets: Record<string, Tokens>
  /**
   * Per session (its transcript's name; a subagent's transcript counts toward
   * the session that started it): the projects it worked in, the days it was
   * active and the models it used.
   */
  sessions: Record<string, { projects: string[]; days: string[]; models: string[] }>
}


export function emptyIndex(): UsageIndex {
  return { version: 3, files: {}, buckets: {}, sessions: {}, ids: [] }
}

/**
 * The session a transcript belongs to: its own name for a session's
 * transcript (`<project>/<session>.jsonl`), the folder it sits under for a
 * subagent's (`<project>/<session>/subagents/agent-<id>.jsonl`).
 */
export function sessionOf(relative: string): string {
  const parts = relative.split('/').filter(Boolean)
  if (parts.length >= 3) return parts[1] ?? ''

  return (parts[parts.length - 1] ?? '').replace(/\.jsonl$/, '')
}

/** Reads a stored index; anything else, an index of another version included, starts over. */
export function asIndex(value: unknown): UsageIndex {
  const index = value as Partial<UsageIndex> | null
  if (!index || index.version !== 3 || typeof index.files !== 'object' || typeof index.buckets !== 'object' || typeof index.sessions !== 'object' || !Array.isArray(index.ids)) {
    return emptyIndex()
  }

  return index as UsageIndex
}

/**
 * The scan: bytes `$3`.. `$2` of transcript `$1` (`$4` of them), each
 * assistant line with a usage reduced to tab-separated fields: time, working
 * directory, model, message id, then input, cache write, cache read and
 * output tokens. Every field is the first of its key, and the token keys are
 * looked for only in the usage object, whose keys come in no fixed order. A
 * line is printed once the next one starts or the bytes end on its newline,
 * so a line cut by the end of the range is left for the next scan; the last
 * line printed, `#` and a count, is how many bytes the complete lines took.
 */
export const SCAN_SCRIPT = [
  'head -c "$2" "$1" | tail -c +"$3" | LC_ALL=C awk -v size="$4" \'',
  'function str(key, text) { if (match(text, "\\"" key "\\":\\"[^\\"]*\\"")) return substr(text, RSTART + length(key) + 4, RLENGTH - length(key) - 5); return "" }',
  'function num(key, text) { if (match(text, "\\"" key "\\":[0-9]+")) return substr(text, RSTART + length(key) + 3, RLENGTH - length(key) - 3); return 0 }',
  '{',
  '  if (pending != "") print pending',
  '  pending = ""; last = length($0) + 1; total += last',
  '  if (index($0, "\\"type\\":\\"assistant\\"") && (u = index($0, "\\"usage\\":{\\""))) {',
  '    s = substr($0, u, 600)',
  '    pending = str("timestamp", $0) "\\t" str("cwd", $0) "\\t" str("model", $0) "\\t" str("id", $0) "\\t" num("input_tokens", s) "\\t" num("cache_creation_input_tokens", s) "\\t" num("cache_read_input_tokens", s) "\\t" num("output_tokens", s)',
  '  }',
  '}',
  'END { if (total <= size) { if (pending != "") print pending; print "#\\t" total } else print "#\\t" (total - last) }\'',
].join('\n')

/** How many bytes of the range the scan counted: up to the end of its last complete line. */
export function scannedBytes(stdout: string): number {
  const line = stdout.trimEnd().split('\n').pop() ?? ''

  return line.startsWith('#\t') ? Number(line.slice(2)) : 0
}

/** The scan's lines as records; a line without a message id or a time is left out. */
export function parseScan(stdout: string): ScanRecord[] {
  return stdout
    .split('\n')
    .map(line => line.split('\t'))
    .filter(parts => parts.length === 8 && parts[0] !== '' && (parts[3] ?? '').startsWith('msg_'))
    .map(([at = '', cwd = '', model = '', id = '', input = '0', cacheWrite = '0', cacheRead = '0', output = '0']) => ({
      at,
      cwd: cwd.replace(/\\\\/g, '\\'),
      model,
      id,
      input: Number(input),
      cacheWrite: Number(cacheWrite),
      cacheRead: Number(cacheRead),
      output: Number(output),
    }))
}

/** The local date of an ISO time, `YYYY-MM-DD`, by the offset the environment answers for that instant. */
export function localDay(iso: string, offsetMinutes?: number): string {
  const at = Date.parse(iso)
  const local = new Date(at - (offsetMinutes ?? new Date(at).getTimezoneOffset()) * 60_000)

  return local.toISOString().slice(0, 10)
}

/** A project's name: the last folder of the directory a session worked in. */
export function projectOf(cwd: string): string {
  const parts = cwd.split(/[\\/]/).filter(Boolean)

  return parts[parts.length - 1] ?? cwd
}

function addTokens(into: Tokens | undefined, record: Pick<ScanRecord, 'input' | 'output' | 'cacheRead' | 'cacheWrite'>): Tokens {
  const base = into ?? { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, responses: 0 }

  return {
    input: base.input + record.input,
    output: base.output + record.output,
    cacheRead: base.cacheRead + record.cacheRead,
    cacheWrite: base.cacheWrite + record.cacheWrite,
    responses: base.responses + 1,
  }
}

/**
 * Adds one transcript's newly read records to the index, each message id
 * once across every transcript, and moves its offset to `offset`. `seen` is
 * the set of ids counted, which this adds to; the index passed in is not
 * changed, and the one returned leaves its `ids` to be written from `seen`.
 */
export function addRecords(
  index: UsageIndex,
  seen: Set<string>,
  file: string,
  session: string,
  records: ScanRecord[],
  offset: number,
  offsetMinutes?: number,
): UsageIndex {
  const buckets = { ...index.buckets }
  const sessions = { ...index.sessions }
  for (const record of records) {
    if (seen.has(record.id)) continue
    seen.add(record.id)
    const day = localDay(record.at, offsetMinutes)
    const project = projectOf(record.cwd)
    const key = `${day}\t${record.model}\t${project}`
    buckets[key] = addTokens(buckets[key], record)
    const known = sessions[session] ?? { projects: [], days: [], models: [] }
    sessions[session] = {
      projects: known.projects.includes(project) ? known.projects : [...known.projects, project],
      days: known.days.includes(day) ? known.days : [...known.days, day],
      models: known.models.includes(record.model) ? known.models : [...known.models, record.model],
    }
  }

  return { ...index, buckets, sessions, files: { ...index.files, [file]: { offset } } }
}


/** All four kinds of tokens together. */
export function totalOf(tokens: Tokens): number {
  return tokens.input + tokens.output + tokens.cacheRead + tokens.cacheWrite
}

/** Cache reads over the input the model read: input plus cache reads. Null with neither. */
export function cacheReuse(tokens: Tokens): number | null {
  const read = tokens.input + tokens.cacheRead

  return read === 0 ? null : tokens.cacheRead / read
}

/** The day `count - 1` days before `today`, `YYYY-MM-DD`. */
function daysBack(today: string, count: number): string {
  return new Date(Date.parse(`${today}T00:00:00Z`) - (count - 1) * 86_400_000).toISOString().slice(0, 10)
}

/**
 * The index summed over the last `days` days up to `today`, or over all of it
 * when `days` is null; rankings keep the `top` largest.
 */
export function summarize(index: UsageIndex, days: number | null, today: string, top = 5): UsageSummary {
  const days_ = Object.keys(index.buckets).map(key => key.split('\t')[0] ?? '')
  const first = days === null ? (days_.sort()[0] ?? today) : daysBack(today, days)
  const zero = (): Tokens => ({ input: 0, output: 0, cacheRead: 0, cacheWrite: 0, responses: 0 })
  const add = (a: Tokens, b: Tokens): Tokens => ({
    input: a.input + b.input,
    output: a.output + b.output,
    cacheRead: a.cacheRead + b.cacheRead,
    cacheWrite: a.cacheWrite + b.cacheWrite,
    responses: a.responses + b.responses,
  })
  let totals = zero()
  const byDay = new Map<string, Tokens>()
  const byModel = new Map<string, Tokens>()
  const byProject = new Map<string, Tokens>()
  for (const [key, tokens] of Object.entries(index.buckets)) {
    const [day = '', model = '', project = ''] = key.split('\t')
    if (day < first || day > today) continue
    totals = add(totals, tokens)
    byDay.set(day, add(byDay.get(day) ?? zero(), tokens))
    byModel.set(model, add(byModel.get(model) ?? zero(), tokens))
    byProject.set(project, add(byProject.get(project) ?? zero(), tokens))
  }
  const active = Object.values(index.sessions).filter(session => session.days.some(day => day >= first && day <= today))
  const rank = (map: Map<string, Tokens>, sessionsOf: (name: string) => number): RankRow[] =>
    [...map.entries()]
      .map(([name, tokens]) => ({ name, tokens, sessions: sessionsOf(name) }))
      .sort((a, b) => totalOf(b.tokens) - totalOf(a.tokens))
      .slice(0, top)
  const daily: UsageSummary['daily'] = []
  for (let at = Date.parse(`${first}T00:00:00Z`); at <= Date.parse(`${today}T00:00:00Z`); at += 86_400_000) {
    const day = new Date(at).toISOString().slice(0, 10)
    daily.push({ day, tokens: byDay.get(day) ?? zero() })
  }

  return {
    totals,
    daily,
    models: rank(byModel, name => active.filter(session => session.models.includes(name)).length),
    projects: rank(byProject, name => active.filter(session => session.projects.includes(name)).length),
    sessions: active.length,
  }
}

/** A token count in a few characters: `873`, `12.4k`, `221.6M`, `1.9B`. */
export function compactCount(value: number): string {
  if (value < 1000) return String(value)
  const units: [number, string][] = [
    [1e9, 'B'],
    [1e6, 'M'],
    [1e3, 'k'],
  ]
  for (const [size, unit] of units) if (value >= size) return `${(value / size).toFixed(1)}${unit}`

  return String(value)
}

/** Message ids written to one file: well under the engine's 4 MiB a read or a write takes. */
export const IDS_PER_FILE = 80_000

/**
 * The index as written: its ids in files of their own, `IDS_PER_FILE` to a
 * file, and the index naming how many there are; the engine reads and writes
 * at most 4 MiB at a time, and a machine's ids pass that.
 */
export function indexToStore(index: UsageIndex, ids: readonly string[]): { index: UsageIndex & { idFiles: number }; idFiles: string[][] } {
  const idFiles: string[][] = []
  for (let start = 0; start < ids.length; start += IDS_PER_FILE) idFiles.push(ids.slice(start, start + IDS_PER_FILE))

  return { index: { ...index, ids: [], idFiles: idFiles.length }, idFiles }
}

