  model: string
  effort: string | null
  sandbox: string
  approvals: string
  tokens: { input: number; cached: number; output: number }
}

export type CodexRuns = Record<string, CodexRun>

/** The Codex login this session's Codex uses, as `codex app-server` reports it. */
